-- One-off venue pass 2026-11-14: wineries, breweries, taprooms and distilleries, all regions.
-- Sources loaded: Temecula Valley Winegrowers Association event pages (temeculawines.org), South Coast Winery event calendar,
-- Ramona Valley Vineyard Association (ramonavalleyvineyards.com, addmi.com ticket page), Bernardo Winery, Stone Brewing,
-- Lucas & Lewellen (llwine.com), Beachwood Brewing (beachwoodbrewing.com/events), Agua Dulce Winery (aguadulcewinery.com).
-- Photos left empty: winery pages have no event-specific photo that passed the photo rules.
ON CONFLICT(id) DO UPDATE SET name=excluded.name, county=excluded.county, city=excluded.city,
  type=excluded.type, start_date=excluded.start_date, end_date=excluded.end_date, status=excluded.status,
  free=excluded.free, price=excluded.price, hours=excluded.hours, lat=excluded.lat, lng=excluded.lng,
  blurb=excluded.blurb, url=excluded.url, season=excluded.season,
  venue=excluded.venue, address=excluded.address, updated_at=datetime('now');

-- Existing Temecula winery events: 2026 dates now published on the TVWA event pages and South Coast Winery's calendar.
UPDATE events SET start_date='2026-11-28', end_date='2026-11-28', status='confirmed', free=1, price='Free; RSVP required', hours='4pm–8pm', url='https://www.temeculawines.org/event/15/annual-tree-lighting-11-28-2026/', blurb='Free family tree lighting in the winery courtyard with live holiday music, a cocoa bar and tractor rides; Santa photos, crafts and a petting zoo cost extra.', updated_at=datetime('now') WHERE id='g15-south-coast-tree-lighting';
UPDATE events SET status='confirmed', price='Free', hours='5pm–8pm', url='https://www.temeculawines.org/event/32/european-holiday-market-11-27-2026/', updated_at=datetime('now') WHERE id='g15-europa-village-holiday-market';
